                <label class="block text-xs font-semibold text-[#1C1917] dark:text-[#F5F2EA]">Keterangan Layanan<textarea name="deskripsi" rows="3" maxlength="2000" x-model="layananDeskripsi" class="mt-1.5 w-full rounded-xl border border-[#E2DDD0] bg-[#FAF8F1] px-3.5 py-3 text-sm text-[#1C1917] outline-none focus:border-[#E09F09] dark:border-[#363126] dark:bg-[#24211B] dark:text-[#F5F2EA]"></textarea></label>
                <div class="flex flex-col-reverse gap-2 pt-2 sm:flex-row sm:justify-end"><button type="button" x-on:click="layananModal=false" class="inline-flex items-center justify-center gap-1.5 rounded-xl border border-[#ECE8DA] px-4 py-3 text-sm font-semibold text-[#6B665C] dark:border-[#302C23] dark:text-[#D4CDBF]">Batal</button><button type="submit" class="inline-flex items-center justify-center gap-1.5 rounded-xl bg-[#E09F09] px-4 py-3 text-sm font-semibold text-[#1A1302] hover:bg-[#C78A05] dark:bg-[#F5B316] dark:hover:bg-[#E09F09]"><i data-lucide="save" stroke-width="1.75" class="h-4 w-4 shrink-0"></i>Simpan Layanan</button></div>
            </form>
        </section>
    </div>
</section>

<script>
function unitUsahaManager() {
    const unitUpdateTemplate = @js(route('pengelola.unit-usaha.update', ['unitUsaha' => '__UNIT__']));
    const layananStoreTemplate = @js(route('pengelola.unit-usaha.layanan.store', ['unitUsaha' => '__UNIT__']));
    const layananUpdateTemplate = @js(route('pengelola.unit-usaha.layanan.update', ['unitUsaha' => '__UNIT__', 'layanan' => '__LAYANAN__']));
    return {
        unitModal: false, editingUnit: false, unitAction: @js(route('pengelola.unit-usaha.store')),
        unitNama: '', unitPic: '', unitDeskripsi: '', unitAktif: '1',
        layananModal: false, editingLayanan: false, layananAction: '', layananUnitNama: '', layananNama: '', layananTarif: '', layananSatuan: '', layananDeskripsi: '', layananJenis: 'BULANAN', layananKatalog: false,
        buatUnit() { this.editingUnit=false; this.unitAction=@js(route('pengelola.unit-usaha.store')); this.unitNama=''; this.unitPic=''; this.unitDeskripsi=''; this.unitAktif='1'; this.unitModal=true; },
        ubahUnit(unit) { this.editingUnit=true; this.unitAction=unitUpdateTemplate.replace('__UNIT__', unit.id); this.unitNama=unit.nama_unit; this.unitPic=unit.penanggung_jawab; this.unitDeskripsi=unit.deskripsi || ''; this.unitAktif=unit.status_aktif ? '1' : '0'; this.unitModal=true; },
        buatLayanan(unitId, namaUnit) { this.editingLayanan=false; this.layananAction=layananStoreTemplate.replace('__UNIT__', unitId); this.layananUnitNama=namaUnit; this.layananNama=''; this.layananTarif=''; this.layananSatuan='Bulan'; this.layananDeskripsi=''; this.layananJenis='BULANAN'; this.layananKatalog=false; this.layananModal=true; },
        ubahLayanan(unitId, namaUnit, layanan) { this.editingLayanan=true; this.layananAction=layananUpdateTemplate.replace('__UNIT__', unitId).replace('__LAYANAN__', layanan.id); this.layananUnitNama=namaUnit; this.layananNama=layanan.nama_layanan; this.layananTarif=layanan.tarif_dasar; this.layananSatuan=layanan.satuan; this.layananDeskripsi=layanan.deskripsi || ''; this.layananJenis=layanan.jenis_layanan || 'BULANAN'; this.layananKatalog=!!layanan.tampil_di_katalog; this.layananModal=true; }
    };
}
</script>
@endsection
